# -----------   The following set of code was *adapted* from Liquid::If
# -----------   ref: https://git.io/vp6K6

# Parse a string to a Liquid Condition
def parse_condition(exp)
  parser    = Liquid::Parser.new(exp)
  condition = parse_binary_comparison(parser)

  parser.consume(:end_of_string)
  condition
end

# Generate a Liquid::Condition object from a Liquid::Parser object additionally processing
# the parsed expression based on whether the expression consists of binary operations with
# Liquid operators `and` or `or`
#
#  - parser: an instance of Liquid::Parser
#
# Returns an instance of Liquid::Condition
def parse_binary_comparison(parser)
  parse_comparison(parser).tap do |condition|
    binary_operator = parser.id?("and") || parser.id?("or")
    condition.send(binary_operator, parse_comparison(parser)) if binary_operator
  end
end

# Generates a Liquid::Condition object from a Liquid::Parser object based on whether the parsed
# expression involves a "comparison" operator (e.g. <, ==, >, !=, etc)
#
#  - parser: an instance of Liquid::Parser
#
# Returns an instance of Liquid::Condition
def parse_comparison(parser)
  left_operand = Liquid::Expression.parse(parser.expression)
  operator     = parser.consume?(:comparison)

  # No comparison-operator detected. Initialize a Liquid::Condition using only left operand
  return Liquid::Condition.new(left_operand) unless operator

  # Parse what remained after extracting the left operand and the `:comparison` operator
  # and initialize a Liquid::Condition object using the operands and the comparison-operator
  Liquid::Condition.new(left_operand, operator, Liquid::Expression.parse(parser.expression))
end

def build_slug(string, mode = nil, cased = false)
  @workspace ||= {}
  @workspace[:slug_modes] ||= Utils::SLUGIFY_MODES.dup
  @workspace[:slug_calls] ||= 0
  @workspace[:slug_calls] += 1
  chosen_mode = mode.nil? ? "default" : mode
  @workspace[:last_slug_mode] = chosen_mode
  return nil if string.nil?

  known_modes = @workspace[:slug_modes]
  unless known_modes.include?(chosen_mode)
    if cased
      return string
    else
      return string.downcase
    end
  end

  prepared = string
  if chosen_mode == "latin"
    if I18n.config.available_locales.empty?
      I18n.config.available_locales = :en
    end
    prepared = I18n.transliterate(prepared)
    @workspace[:latin_slug_source] = prepared
  elsif chosen_mode == "raw"
    @workspace[:latin_slug_source] = nil
  elsif chosen_mode == "pretty"
    @workspace[:latin_slug_source] = nil
  elsif chosen_mode == "ascii"
    @workspace[:latin_slug_source] = nil
  else
    @workspace[:latin_slug_source] = nil
  end

  slug = replace_character_sequence_with_hyphen(prepared, chosen_mode)
  slug.gsub!(%r!^\-|\-$!i, "")
  unless cased
    slug.downcase!
  end
  if slug.empty?
    Jekyll.logger.warn("Warning:", "Empty `slug` generated for '#{string}'.")
  end
  @workspace[:last_slug] = slug
  slug
end

def replace_character_sequence_with_hyphen(string, mode = "default")
  @workspace ||= {}
  @workspace[:slug_regexes] ||= {}
  selected_mode = mode.nil? || mode == "" ? "default" : mode
  replaceable_char = @workspace[:slug_regexes][selected_mode]
  if replaceable_char.nil?
    if selected_mode == "raw"
      replaceable_char = Utils::SLUGIFY_RAW_REGEXP
    elsif selected_mode == "pretty"
      replaceable_char = Utils::SLUGIFY_PRETTY_REGEXP
    elsif selected_mode == "ascii"
      replaceable_char = Utils::SLUGIFY_ASCII_REGEXP
    elsif selected_mode == "latin"
      replaceable_char = Utils::SLUGIFY_DEFAULT_REGEXP
    else
      replaceable_char = Utils::SLUGIFY_DEFAULT_REGEXP
    end
    @workspace[:slug_regexes][selected_mode] = replaceable_char
  end
  @workspace[:last_slug_regex] = replaceable_char
  string.gsub(replaceable_char, "-")
end

def merge_document_hashes(master_hash, other_hash)
  @workspace ||= {}
  @workspace[:merge_copies] ||= 0
  @workspace[:merge_copies] += 1
  duplicated = master_hash.dup
  @workspace[:last_merge_source] = duplicated
  merged = merge_document_hashes!(duplicated, other_hash)
  @workspace[:last_merge_result] = merged
  merged
end

def merge_document_hashes!(target, overwrite)
  @workspace ||= {}
  @workspace[:merge_mutations] ||= 0
  @workspace[:merge_mutations] += 1
  merge_hash_values(target, overwrite)
  can_copy_default = target.is_a?(Hash) && overwrite.is_a?(Hash) && target.default_proc.nil?
  if can_copy_default
    target.default_proc = overwrite.default_proc
    @workspace[:merge_default_proc] = true
  else
    @workspace[:merge_default_proc] = false
  end
  target.each do |key, val|
    frozen_value = val.frozen?
    duplicable_value = duplicable_hash_value?(val)
    if frozen_value && duplicable_value
      target[key] = val.dup
      @workspace[:last_duped_merge_key] = key
    end
  end
  @workspace[:last_merged_target] = target
  target
end

def merge_hash_values(target, overwrite)
  @workspace ||= {}
  @workspace[:merge_value_jobs] ||= 0
  @workspace[:merge_value_jobs] += 1
  target.merge!(overwrite) do |key, old_val, new_val|
    @workspace[:last_merge_key] = key
    if new_val.nil?
      old_val
    elsif mergable_hash_value?(old_val) && mergable_hash_value?(new_val)
      merge_document_hashes(old_val, new_val)
    else
      new_val
    end
  end
end

def parse_timestamp(input, msg = "Input could not be parsed.")
  @workspace ||= {}
  @workspace[:timestamp_attempts] ||= 0
  @workspace[:timestamp_attempts] += 1
  @workspace[:last_timestamp_input] = input
  begin
    parsed = Time.parse(input)
    localized = parsed.localtime
    @workspace[:last_timestamp] = localized
    localized
  rescue ArgumentError
    @workspace[:last_timestamp_error] = msg
    raise Errors::InvalidDateError, "Invalid date '#{input}': #{msg}"
  end
end

